python3 -c "
# In a reflected CRC (LSB first, shift right):
# crc starts as byte i (in bits 0..7)
# for bit in 0..7:
#   if crc & 1: crc = (crc >> 1) ^ poly_rev
#   else: crc = crc >> 1
# Let's see: if poly_rev is 0x42F0E1EBA9EA3693:
poly = 0x42F0E1EBA9EA3693
for method in ['lsb_first', 'msb_first']:
    table = []
    if method == 'lsb_first':
        for i in range(256):
            crc = i
            for _ in range(8):
                if crc & 1:
                    crc = (crc >> 1) ^ poly
                else:
                    crc = crc >> 1
            table.append(crc)
    else:
        for i in range(256):
            crc = i << 56
            for _ in range(8):
                if crc & 0x8000000000000000:
                    crc = ((crc << 1) & 0xFFFFFFFFFFFFFFFF) ^ poly
                else:
                    crc = (crc << 1) & 0xFFFFFFFFFFFFFFFF
            table.append(crc)
    print(method, 'first 4:', [hex(x) for x in table[:4]])
